import numpy as np
import datetime

def task_func(arr):
    arr = np.asarray(arr)

    def reverse_words(s):
        if isinstance(s, bytes):
            s = s.decode()
        if isinstance(s, str):
            return ".".join(s.split(".")[::-1])
        return s

    return np.vectorize(reverse_words, otypes=[object])(arr)
